import os
os.environ['PLAYWRIGHT_BROWSERS_PATH']='/opt/pw-browsers'
from playwright.sync_api import sync_playwright
B='http://localhost:4182'  # preview of the filled copy built by make-filled-copy.sh
def ok(n,c,x=''): print('PASS' if c else 'FAIL', n, x, flush=True)
with sync_playwright() as p:
    b=p.chromium.launch(); ctx=b.new_context(viewport={'width':1440,'height':900}); ctx.route('https://mail.google.com/**', lambda r: r.fulfill(status=200, content_type='text/html', body='ok')); pg=ctx.new_page(); errs=[]
    pg.on('pageerror',lambda e:errs.append(str(e))); pg.on('console',lambda m: m.type=='error' and '403' not in m.text and 'ERR_NAME_NOT_RESOLVED' not in m.text and errs.append(m.text))
    pg.goto(B); pg.wait_for_timeout(2600)
    body=lambda: pg.evaluate("document.body.innerText")
    t=body()
    need=['Test Person','Test Engineer','I test things for fun.','Testville','Open to tests','Test University','Testing focus']; ok('Home: name, title, intro, location, availability, university all from data', all(x.lower() in t.lower() for x in need), 'missing: '+str([x for x in need if x.lower() not in t.lower()]))
    ok('Home: tab title + status bar + footer use the name', pg.title()=='Home — Test Person' and pg.locator('header.fixed').inner_text().find('Test Person')>=0 and pg.locator('footer').inner_text().find('Test Person')>=0, pg.title())
    ok('Home: no "[YOUR …]" left on screen for filled fields', not any(s in t for s in ['[YOUR NAME]','[YOUR TITLE]','[YOUR PHOTO]','[YOUR LOCATION]','[YOUR UNIVERSITY]','[YOUR DEGREE]']))
    ok('Home: real photo renders as <img> (loaded, correct alt)', pg.evaluate("(()=>{const i=document.querySelector('img[alt=\"Portrait of Test Person\"]');return !!i&&i.naturalWidth>0})()"))
    ok('Home: stats are counted from data (6 projects, 6 certs, 7 achievements)', all(x in t for x in ['PROJECTS\n6','CERTIFICATES\n6','ACHIEVEMENTS\n7']) or pg.evaluate("[...document.querySelectorAll('[data-widget-id=stats] p')].map(p=>p.textContent).join('|')").count('6')>=2, pg.evaluate("[...document.querySelectorAll('[data-widget-id=stats] p')].map(p=>p.textContent).join('|')"))
    ok('Home: CGPA shows 7.5 (not rounded) and "/10"', '7.5/10' in pg.evaluate("document.querySelector('[data-widget-id=stats]').innerText.replace(/\\n/g,'')"))
    ok('Home: no SAMPLE badges once isSample=false', 'SAMPLE' not in t.upper().replace('SAMPLE','SAMPLE') or 'SAMPLE DATA' not in t.upper(), '')
    ok('Home: widget hidden by default via widgets.ts (links)', pg.locator('[data-widget-id=links]').count()==0 and pg.locator('[data-widget-id]').count()==11)
    pg.get_by_role('button',name='Customize').click(); pg.wait_for_timeout(900); ok('Home: hidden widget offered as an "add" chip', pg.get_by_role('button',name='Profiles & links').count()==1)
    pg.get_by_role('button',name='Done').click(); pg.wait_for_timeout(400)
    pg.goto(B+'/about'); pg.wait_for_timeout(1800); ok('About: photo, name, derived location & focus', pg.locator('img[alt="Portrait of Test Person"]').count()==1 and 'Testville' in body() and 'Testing focus' in body())
    pg.goto(B+'/academics'); pg.wait_for_timeout(2200); bt=body(); chk={'university':'Test University' in bt,'degree':'BSc Testing' in bt,'no SAMPLE':'SAMPLE' not in bt.upper(),'7.5':'7.5' in bt}; ok('Academics: real values, no sample badges', all(chk.values()), str(chk)+' '+str([l for l in bt.split(chr(10)) if 'SAMPLE' in l.upper()][:3]))
    pg.goto(B+'/skills'); pg.wait_for_timeout(1500); ok('Skills: sample-levels notice removed', 'SAMPLE LEVELS' not in body().upper())
    pg.goto(B+'/projects'); pg.wait_for_timeout(1800)
    ok('Projects: page title comes from pages.ts', pg.locator('h1').inner_text()=='My Work')
    ok('Projects: real screenshots render for every card', pg.locator('article img[alt$="screenshot"]').count()==6)
    ok('Projects: set GitHub links are live external anchors', pg.locator('article a[href="https://example.com/repo"][target=_blank]').count()==6 and pg.locator('article [aria-disabled=true]').count()==6, '(demo links still placeholders -> disabled)')
    pg.goto(B+'/certificates'); pg.wait_for_timeout(1800); ok('Certificates: image files render, PDFs show a PDF badge', pg.locator('img[alt$="certificate"]').count()==2 and pg.get_by_text('PDF document').count()==4)
    pg.goto(B+'/blog'); pg.wait_for_timeout(1800); ok('Blog: featured cover image renders', pg.locator('article img').count()>=1)
    pg.goto(B+'/blog/post-1'); pg.wait_for_timeout(1500); ok('Blog post: cover image renders', pg.locator('article img').count()==1)
    pg.goto(B+'/resume'); pg.wait_for_timeout(1800); ok('Resume: PDF embed + live open/download', pg.locator('object[data^="/resume.pdf"]').count()==1 and pg.locator('a[download][href="/resume.pdf"]').count()==1)
    ok('Resume: education line derived from academics.ts', 'BSc Testing · Test University' in body())
    pg.goto(B+'/contact'); pg.wait_for_timeout(1800)
    ok('Contact: reply time, location, availability from data', all(s in body() for s in ['Within a day','Testville','Open to tests']))
    ok('Contact: subject chips come from contact.ts', pg.get_by_role('button',name='Hello').count()==1 and pg.get_by_role('button',name='Hire').count()==1 and pg.get_by_role('button',name='Opportunity').count()==0)
    ok('Contact: GitHub card shows data handle and is a live link', '@testgh' in body() and pg.locator('a[href="https://example.com/gh"][target=_blank]').count()==1)
    pg.get_by_role('button',name='Hire').click()
    with pg.expect_popup() as pop: pg.get_by_role('button',name='Open in Gmail').click()
    u=pop.value.url; ok('Contact: Gmail draft uses the data email + chosen subject', 'to=test%40example.com' in u and 'su=Hire' in u)
    pg.goto(B+'/'); pg.wait_for_timeout(1500); pg.keyboard.press('Control+k'); pg.wait_for_timeout(500); pg.keyboard.type('>resume'); pg.wait_for_timeout(300)
    ok('Palette: commands see the live resume link (no "add your PDF" guard needed)', 'Open resume' in pg.evaluate("document.querySelector('[role=listbox]').innerText"))
    ok('no page errors', not errs, ';'.join(errs)[:200]); b.close()
